/* ============================================
   HOVER CARD COMPONENT
   Rich preview panel on hover / focus
   ============================================ */

.ds-hover-card {
  position: relative;
  display: inline-flex;
}

/* ============================================
   PANEL
   Dresses like the other floating panels:
   page-primary fill, hairline, radius-sm,
   floating shadow (see Popover).
   ============================================ */

.ds-hover-card__panel {
  /* Rendered as a <span> so the card survives inside a <p>. */
  position: absolute;
  z-index: 50;
  min-width: 240px;
  max-width: 320px;
  padding: var(--padding-400);
  border-radius: var(--radius-200);
  background-color: var(--color-bg-page-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  box-shadow: var(--shadow-floating);
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  /* display:none keeps the hidden panel out of the accessibility tree and
     tab order AND out of the page's scrollable overflow — an edge-adjacent
     trigger's 240px+ panel would otherwise add horizontal scroll while
     invisible (see Tooltip, where the leak was found). The display flip
     transitions discretely: allow-discrete holds the panel through the exit
     fade, @starting-style below supplies the entry frame; browsers without
     those skip the fades but open and close correctly. */
  display: none;
  opacity: 0;
  transition-property: opacity, transform, display;
  transition-duration: var(--motion-duration-fast);
  transition-timing-function: var(--motion-ease-standard);
  transition-behavior: allow-discrete;
}

.ds-hover-card__panel--visible {
  display: block;
  opacity: 1;
}

/* ============================================
   POSITIONS
   ============================================ */

.ds-hover-card__panel--top {
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  margin-bottom: var(--gap-100);
}

.ds-hover-card__panel--top.ds-hover-card__panel--visible {
  transform: translateX(-50%) translateY(0);
}

.ds-hover-card__panel--bottom {
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  margin-top: var(--gap-100);
}

.ds-hover-card__panel--bottom.ds-hover-card__panel--visible {
  transform: translateX(-50%) translateY(0);
}

.ds-hover-card__panel--left {
  right: 100%;
  top: 50%;
  transform: translateY(-50%) translateX(4px);
  margin-right: var(--gap-100);
}

.ds-hover-card__panel--left.ds-hover-card__panel--visible {
  transform: translateY(-50%) translateX(0);
}

.ds-hover-card__panel--right {
  left: 100%;
  top: 50%;
  transform: translateY(-50%) translateX(-4px);
  margin-left: var(--gap-100);
}

.ds-hover-card__panel--right.ds-hover-card__panel--visible {
  transform: translateY(-50%) translateX(0);
}

/* Entry states for the display flip: a panel arriving from display:none has
   no prior computed style, so these supply the fade's starting frame. Each
   mirrors its position's hidden transform above. */
@starting-style {
  .ds-hover-card__panel--top.ds-hover-card__panel--visible {
    opacity: 0;
    transform: translateX(-50%) translateY(4px);
  }

  .ds-hover-card__panel--bottom.ds-hover-card__panel--visible {
    opacity: 0;
    transform: translateX(-50%) translateY(-4px);
  }

  .ds-hover-card__panel--left.ds-hover-card__panel--visible {
    opacity: 0;
    transform: translateY(-50%) translateX(4px);
  }

  .ds-hover-card__panel--right.ds-hover-card__panel--visible {
    opacity: 0;
    transform: translateY(-50%) translateX(-4px);
  }
}

'use client';

import React, { useEffect, useId, useRef, useState } from 'react';
import './HoverCard.css';
import { MOTION_HOVER_SHOW_DELAY_MS, MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';

type HoverCardOwnProps = {
  /** Trigger element */
  children?: React.ReactNode;
  /** Panel content — arbitrary elements, unlike Tooltip's plain text. In running text inside a `<p>`, keep it phrasing-level (spans): a block element would end the paragraph mid-parse. */
  content: React.ReactNode;
  /** Preferred position */
  position?: 'top' | 'bottom' | 'left' | 'right';
  /** Delay before showing (in ms) */
  showDelay?: number;
  /** Delay before hiding (in ms) */
  hideDelay?: number;
  /** Additional CSS classes */
  className?: string;
};

export interface HoverCardProps
  extends HoverCardOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof HoverCardOwnProps> {}

/**
 * Rich preview panel that opens from hover or focus — a profile card behind
 * a username, a component summary behind a link. Where Tooltip names a
 * control in a line of text, HoverCard previews a destination; its panel is
 * interactive, stays open while the pointer is inside it, and dresses like
 * the other floating panels (Popover, the menus).
 *
 * The hidden panel is `visibility: hidden`, so it stays out of the
 * accessibility tree and tab order until shown. Escape dismisses it.
 */
export const HoverCard = React.forwardRef<HTMLSpanElement, HoverCardProps>(
  (
    {
      children,
      content,
      position = 'bottom',
      showDelay = MOTION_HOVER_SHOW_DELAY_MS,
      hideDelay = MOTION_HOVER_HIDE_DELAY_MS,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const [visible, setVisible] = useState(false);
    const showTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
    const hideTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
    const panelId = useId();

    const baseClass = 'ds-hover-card';

    const show = () => {
      clearTimeout(hideTimeoutRef.current);
      showTimeoutRef.current = setTimeout(() => setVisible(true), showDelay);
    };

    const hide = () => {
      clearTimeout(showTimeoutRef.current);
      hideTimeoutRef.current = setTimeout(() => setVisible(false), hideDelay);
    };

    useEffect(() => {
      return () => {
        clearTimeout(showTimeoutRef.current);
        clearTimeout(hideTimeoutRef.current);
      };
    }, []);

    // Escape dismisses while visible, wherever focus is (WCAG 1.4.13).
    useEffect(() => {
      if (!visible) return;
      const onKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
          clearTimeout(showTimeoutRef.current);
          clearTimeout(hideTimeoutRef.current);
          setVisible(false);
        }
      };
      document.addEventListener('keydown', onKeyDown);
      return () => document.removeEventListener('keydown', onKeyDown);
    }, [visible]);

    // Focus moving within the container (trigger → a link in the panel)
    // must not close the card; only focus leaving it entirely does.
    const handleBlur = (event: React.FocusEvent<HTMLSpanElement>) => {
      if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
        hide();
      }
    };

    const trigger = React.isValidElement(children)
      ? React.cloneElement(children as React.ReactElement<{ 'aria-expanded'?: boolean; 'aria-controls'?: string }>, {
          'aria-expanded': visible,
          'aria-controls': visible ? panelId : undefined,
        })
      : children;

    const containerClasses = [baseClass, className].filter(Boolean).join(' ');
    const panelClasses = [
      `${baseClass}__panel`,
      `${baseClass}__panel--${position}`,
      visible ? `${baseClass}__panel--visible` : '',
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <span
        {...rest}
        ref={ref}
        className={containerClasses}
        onMouseEnter={show}
        onMouseLeave={hide}
        onFocus={show}
        onBlur={handleBlur}
      >
        {trigger}

        {/* A <span> panel, like Tooltip's bubble: the whole card must survive
            inside a <p>, where a <div> would end the paragraph mid-parse. */}
        <span className={panelClasses} id={panelId}>
          {content}
        </span>
      </span>
    );
  },
);

HoverCard.displayName = 'HoverCard';
